parameters.responseBody:
={
  "text": {{ JSON.stringify($json.output) }},
  "card": {{ (() => { 
    try { 
      try { 
        const node = $('Tool: manage_item'); 
        const it = (node && typeof node.first === 'function' ? node.first() : null) || (node ? node.item : null); 
        const j = it ? it.json : null; 
        if (j && j.card) return JSON.stringify(j.card); 
        if (j && typeof j.response === 'string') { 
          const parsed = JSON.parse(j.response); 
          if (parsed && parsed.card) return JSON.stringify(parsed.card); 
        } 
      } catch (e1) {} 
      try { 
        const node = $('Tool: prepare_stock_change'); 
        const it = (node && typeof node.first === 'function' ? node.first() : null) || (node ? node.item : null); 
        const j = it ? it.json : null; 
        if (j && j.card) return JSON.stringify(j.card); 
        if (j && typeof j.response === 'string') { 
          const parsed = JSON.parse(j.response); 
          if (parsed && parsed.card) return JSON.stringify(parsed.card); 
        } 
      } catch (e2) {} 
      return 'null'; 
    } catch (err) { 
      return 'null'; 
    } 
  })() }}
}
